from moler.cmd.unix.hostname import Hostname as MolerHostname
from moler.exceptions import ParsingDone
import re


class Hostname(MolerHostname):
    def _parse_user(self, line):
        if self._regex_helper.search_compiled(Hostname._re_user, line):
            self.current_ret["hostname"] = re.findall(r"(\S+)\s?", line)
            raise ParsingDone
